18	class ChunkedHTTPClient : public HTTPClient {
19	 public:
20	  bool sendPOSTHeaders() {
21	
22	    // connect to server
23	    if(!connect()) {
24	      return returnError(HTTPC_ERROR_CONNECTION_REFUSED);
25	    }
26	
27	    return sendHeader("POST");
28	  }
29	
30	  int handleResponse() {
31	    return handleHeaderResponse();
32	  }
33	};
34	
35	
36	
37	LogViewerScreen::LogViewerScreen() : BaseScreen("Log view", true),
38	                                     _current_view(e_log_main_view),
39	                                     _detail_log_file_path(""),
40	                                     _detail_log_file_name(""),
41	                                     _detail_log_timestamp{},
42	                                     _detail_upload_timestamp{},
43	                                     _detail_log_upload_id(0),
44	                                     _file_count(0),
45	                                     _selected_index(0),
46	                                     _main_selected_index(0),
47	                                     _upload_status(e_upload_idle),
48	                                     _upload_http_code(0) {
49	  required_wifi = true;
50	  required_sd = true;
51	  _file_list[0][0] = '\0';
52	}
53	
54	const char* LogViewerScreen::current_dir() const {
55	  switch (_current_view) {
56	    case e_log_drive_view:   return DRIVE_LOG_DIRECTORY;
57	    case e_log_survey_view:  return SURVEY_LOG_DIRECTORY;
58	    case e_log_journal_view: return JOURNAL_LOG_DIRECTORY;
59	    default:                 return nullptr;
60	  }
61	}
62	
63	void LogViewerScreen::load_log_list(const char* dir) {
64	  _file_count = 0;
65	  _selected_index = 0;
66	  if (!dir) return;
67	
68	  File root = SD.open(dir, FILE_READ);
69	  if (!root || !root.isDirectory()) {
70	    if (root) root.close();
71	    return;
72	  }
73	
74	  while (_file_count < LOG_LIST_MAX) {
75	    File entry = root.openNextFile();
76	    if (!entry) break;
77	    if (!entry.isDirectory()) {
78	      const char* name = entry.name();
79	      // entry.name() may include the leading directory; keep the basename only
80	      const char* slash = strrchr(name, '/');
81	      const char* base = slash ? slash + 1 : name;
82	      // Filter for .log files; skip "latest.log" (still being written)
83	      const char* dot = strrchr(base, '.');
84	      if (dot && strcmp(dot, ".log") == 0 && strcmp(base, "latest.log") != 0) {
85	        strncpy(_file_list[_file_count], base, LOG_NAME_MAX - 1);
86	        _file_list[_file_count][LOG_NAME_MAX - 1] = '\0';
87	        _file_count++;
88	      }
89	    }
90	    entry.close();
91	  }
92	  root.close();
93	
94	  // Sort latest first. Dated names (YYYY-MM-DD_HHMM.log) sort lexicographically;
95	  // descending strcmp gives newest at the top.
96	  for (int i = 1; i < _file_count; i++) {
97	    for (int j = i; j > 0 && strcmp(_file_list[j - 1], _file_list[j]) < 0; j--) {
98	      char tmp[LOG_NAME_MAX];
99	      strncpy(tmp, _file_list[j - 1], LOG_NAME_MAX);
100	      strncpy(_file_list[j - 1], _file_list[j], LOG_NAME_MAX);
101	      strncpy(_file_list[j], tmp, LOG_NAME_MAX);
102	    }
103	  }
104	}
105	
106	BaseScreen* LogViewerScreen::handle_input(Controller& controller, const worker_map_t& workers) {
107	  auto button1 = workers.worker<ZenButton>(k_worker_button_1);
108	  auto button2 = workers.worker<ZenButton>(k_worker_button_2);
109	  auto button3 = workers.worker<ZenButton>(k_worker_button_3);
110	
111	
112	  if (strlen(_detail_log_file_name) > 0) {
113	    // detail view
114	    if (button1->is_fresh() && button1->get_data().shortPress) {
115	      force_next_render();
116	      if (!_detail_log_upload_id) {
117	        // Upload
118	        upload_detail(controller.get_settings());
119	      }
120	    }
121	    if (button3->is_fresh() && button3->get_data().shortPress) {
122	      // Back: detail -> list
123	      force_next_render();
124	      leave_detail();
125	      return nullptr;
126	    }
127	  } else if (_current_view == e_log_main_view) {
128	    // category selector
129	    if (button1->is_fresh() && button1->get_data().shortPress) {
130	      force_next_render();
131	      _main_selected_index = (_main_selected_index + 1) % MAIN_VIEW_ITEM_COUNT;
132	      return nullptr;
133	    }
134	    if (button2->is_fresh() && button2->get_data().shortPress) {
135	      force_next_render();
136	      switch (_main_selected_index) {
137	        case 0: _current_view = e_log_drive_view;   break;
138	        case 1: _current_view = e_log_survey_view;  break;
139	        case 2: _current_view = e_log_journal_view; break;
140	      }
141	      load_log_list(current_dir());
142	      return nullptr;
143	    }
144	    if (button3->is_fresh() && button3->get_data().shortPress) {
145	      // Back: main -> menu
146	      return &MenuWindow_i;
147	    }
148	  } else {
149	    // file list view
150	    const int total_rows = _file_count + 1; // row 0 reserved historically; we no longer render it
151	    if (button1->is_fresh() && button1->get_data().shortPress) {
152	      force_next_render();
153	      if (_file_count > 0) {
154	        _selected_index = (_selected_index + 1) % _file_count;
155	      }
156	      return nullptr;
157	    }
158	    if (button2->is_fresh() && button2->get_data().shortPress) {
159	      force_next_render();
160	      if (_file_count == 0) {
161	        return nullptr;
162	      }
163	      char full_path[LOG_FILENAME_SIZE];
164	      snprintf(full_path, LOG_FILENAME_SIZE, "%s/%s",
165	               current_dir(), _file_list[_selected_index]);
166	      enter_detail(full_path);
167	      return nullptr;
168	    }
169	    if (button3->is_fresh() && button3->get_data().shortPress) {
170	      // Back: list -> main
171	      force_next_render();
172	      _current_view = e_log_main_view;
173	      _selected_index = 0;
174	      _file_count = 0;
175	      return nullptr;
176	    }
177	  }
178	
179	  return nullptr;
180	}
181	
182	void LogViewerScreen::render(const worker_map_t& workers, const handler_map_t& handlers, bool force) {
183	  if (!force) {
184	    return;
185	  }
186	
187	  clear_screen_content();
188	
189	  if (strlen(_detail_log_file_name) > 0) {
190	    return render_log_detail(workers, handlers, force);
191	  }
192	
193	  switch (_current_view) {
194	    case e_log_main_view:
195	      return render_main(workers, handlers, force);
196	    case e_log_drive_view:
197	    case e_log_survey_view:
198	    case e_log_journal_view:
199	      return render_log_list(current_dir(), workers, handlers, force);
200	    default:
201	      return;
202	  }
203	}
204	
205	void LogViewerScreen::render_main(const worker_map_t& workers, const handler_map_t& handlers, bool force) {
206	  drawButton1("Down");
207	  drawButton2("Select");
208	  drawButton3("Back");
209	
210	  M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
211	  M5.Lcd.setCursor(0, 40, &fonts::Font2);
212	
213	  const char* labels[MAIN_VIEW_ITEM_COUNT] = {"Drive logs", "Survey logs", "Journal logs"};
214	  for (int i = 0; i < MAIN_VIEW_ITEM_COUNT; i++) {
215	    M5.Lcd.printf("%s  %s\n", (i == _main_selected_index) ? ">" : " ", labels[i]);
216	  }
217	}
218	
219	void LogViewerScreen::render_log_list(const char* dir, const worker_map_t& workers, const handler_map_t& handlers, bool force) {
220	  drawButton1("Down");
221	  drawButton2("Select");
222	  drawButton3("Back");
223	
224	  M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
225	  M5.Lcd.setCursor(0, 40, &fonts::Font2);
226	
227	  if (_file_count == 0) {
228	    M5.Lcd.printf("%s/\n", dir ? dir : "");
229	    M5.Lcd.printf("   (no logs)\n");
230	    return;
231	  }
232	
233	  const int total_pages = (_file_count + LOG_LIST_PAGE - 1) / LOG_LIST_PAGE;
234	  const int page = _selected_index / LOG_LIST_PAGE;
235	  const int start = page * LOG_LIST_PAGE;
236	  const int end = (start + LOG_LIST_PAGE < _file_count) ? start + LOG_LIST_PAGE : _file_count;
237	  M5.Lcd.printf("%s/  (%d/%d)\n", dir ? dir : "", page + 1, total_pages);
238	  for (int i = start; i < end; i++) {
239	    M5.Lcd.printf("%s  %s\n",
240	                  (i == _selected_index) ? ">" : " ",
241	                  _file_list[i]);
242	  }
243	}
244	
245	void LogViewerScreen::render_log_detail(const worker_map_t& workers, const handler_map_t& handlers, bool force) {
246	  const bool can_upload = !_detail_log_upload_id
247	                          && WiFiWrapper_i.wifi_connected()
248	                          && _upload_status != e_upload_in_progress;
249	  drawButton1("Upload", can_upload ? e_button_default : e_button_disabled);
250	  drawButton2("");
251	  drawButton3("Back");
252	
253	  M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
254	  M5.Lcd.setCursor(0, 40, &fonts::Font2);
255	
256	  M5.Lcd.printf("Log name:      %s\n", _detail_log_file_name);
257	  M5.Lcd.printf("Timestamp:     %04hu/%02hhu/%02hhu %02hhu:%02hhu\n", _detail_log_timestamp.year, _detail_log_timestamp.month, _detail_log_timestamp.day, _detail_log_timestamp.hour, _detail_log_timestamp.minute);
258	  M5.Lcd.printf("WiFi:          %s\n", WiFiWrapper_i.wifi_connected() ? "connected" : "connecting...");
259	
260	  switch (_upload_status) {
261	    case e_upload_idle:
262	      M5.Lcd.printf("Status:        ready\n");
263	      break;
264	    case e_upload_in_progress:
265	      M5.Lcd.printf("Status:        uploading...\n");
266	      break;
267	    case e_upload_success:
268	      M5.Lcd.printf("Status:        OK (HTTP %d)\n", _upload_http_code);
269	      break;
270	    case e_upload_failed:
271	      M5.Lcd.printf("Status:        FAILED (HTTP %d)\n", _upload_http_code);
272	      break;
273	  }
274	  if (_detail_log_upload_id) {
275	    M5.Lcd.printf("Upload log id: %u\n", _detail_log_upload_id);
276	  }
277	}
278	
279	void LogViewerScreen::enter_detail(const char* log_name) {
280	  char dir[100];
281	  strcpy(_detail_log_file_path, log_name);
282	  if (sscanf(_detail_log_file_path, "/%[^/]/%s", dir, _detail_log_file_name) == 0) {
283	    strcpy(_detail_log_file_name, "Unknown log name");
284	    return;
285	  }
286	  if (sscanf(_detail_log_file_name, "%4hu-%2hhu-%2hhu_%2hhu%2hhu.log", &_detail_log_timestamp.year, &_detail_log_timestamp.month, &_detail_log_timestamp.day, &_detail_log_timestamp.hour, &_detail_log_timestamp.minute) != 5) {
287	    _detail_log_timestamp.clear();
288	  }
289	
290	  // TODO: parse log_name
291	}
292	
293	void LogViewerScreen::leave_detail() {
294	  strcpy(_detail_log_file_name, "");
295	  _detail_log_timestamp.clear();
296	  _detail_upload_timestamp.clear();
297	  _detail_log_upload_id = 0;
298	  _upload_status = e_upload_idle;
299	  _upload_http_code = 0;
300	}
301	
302	void LogViewerScreen::enter_screen(Controller& controller) {
303	  leave_detail();
304	  _current_view = e_log_main_view;
305	  _main_selected_index = 0;
306	  _selected_index = 0;
307	  _file_count = 0;
308	  // Use the active WiFi profile (consistent with fixed_mode / api_connector).
309	  // first_time=true to force a fresh begin() rather than a passive reconnect,
310	  // since other screens may have soft-disconnected the radio.
311	  const auto& s = controller.get_settings();
312	  WiFiWrapper_i.connect_wifi(s.get_active_wifi_ssid(), s.get_active_wifi_password(), true);
313	}
314	
315	void LogViewerScreen::leave_screen(Controller& controller) {
316	  // Do not disconnect on leave: api_connector / fixed_mode etc. manage their own
317	  // lifecycle and will turn WiFi off when appropriate. Leaving WiFi up reduces
318	  // reconnect churn on Core2 where disconnect/reconnect cycles cost seconds.
319	}
320	
321	void LogViewerScreen::upload_detail(const LocalStorage& config) {
322	  _upload_status = e_upload_in_progress;
323	  _upload_http_code = 0;
324	  // Paint a quick "uploading" line directly so the user sees feedback before we block.
325	  M5.Lcd.setTextColor(LCD_COLOR_DEFAULT, LCD_COLOR_BACKGROUND);
326	  M5.Lcd.setCursor(0, 120, &fonts::Font2);
327	  M5.Lcd.printf("Uploading...                ");
328	
329	  File log_file = SDInterface::i().get_file(_detail_log_file_path);
330	
331	  if (!log_file) {
332	    M5_LOGD("Failed to open log file!");
333	    _upload_status = e_upload_failed;
334	    return;
335	  }
336	
337	  char url[160];
338	  snprintf(url, sizeof(url), "%s?api_key=%s", API_LOGFILE_ENDPOINT, config.get_api_key());
339	
340	  ChunkedHTTPClient http;
341	  WiFiClientSecure client;
342	  // TODO: pin Safecast CA bundle. Using setInsecure() until cert plumbing lands.
343	  client.setInsecure();
344	
345	  // Specify destination for HTTPS request
346	  if (!http.begin(client, url)) {
347	    M5_LOGD("Unable to begin URL connection");
348	    http.end(); // Free resources
349	    log_file.close();
350	    _upload_status = e_upload_failed;
351	    return;
352	  }
353	
354	  // Define boundary and headers
355	  char boundary[32];
356	  sprintf(boundary, "----WebKitFormBoundaryZen%d", config.get_device_id());
357	  char content_type_header[150];
358	  sprintf(content_type_header, "multipart/form-data; boundary=%s", boundary);
359	
360	  http.setUserAgent(HEADER_API_USER_AGENT);
361	  // HTTPClient sets Host: from the URL; do not duplicate it here.
362	  http.addHeader("Content-Type", content_type_header);
363	  http.addHeader("Transfer-Encoding", "chunked");
364	  http.addHeader("Accept", "application/json");
365	
366	  char chunk_header[16];
367	  static constexpr size_t CHUNK_BUF_SZ = 1024;
368	  char chunk_buffer[CHUNK_BUF_SZ];
369	  size_t chunk_length;
370	
371	  if (http.sendPOSTHeaders()) {
372	    // 1. Send the opening boundary and metadata for the file part as a chunk
373	    // RFC 7578: each part = boundary line, headers, blank line, body, CRLF before next boundary.
374	    sprintf(chunk_buffer,
375	            "--%s\r\n"
376	            "Content-Disposition: form-data; name=\"bgeigie_import[description]\"\r\n"
377	            "\r\n"
378	            "Uploaded from Zen\r\n"
379	            "--%s\r\n"
380	            "Content-Disposition: form-data; name=\"bgeigie_import[source]\"; filename=\"%s\"\r\n"
381	            "Content-Type: text/plain\r\n"
382	            "\r\n",
383	            boundary, boundary, _detail_log_file_name);
384	
385	    // Calculate header length
386	    chunk_length = strlen(chunk_buffer);
387	    sprintf(chunk_header, "%X\r\n", chunk_length); // Chunk size in hexadecimal
388	    client.print(chunk_header);              // Send chunk size
389	    client.print(chunk_buffer);   // Send chunk data
390	    client.print("\r\n");                                   // End of chunk
391	    M5_LOGD("Header chunk sent (%X):\n%s", chunk_length, chunk_buffer);
392	
393	    // 2. Stream the file content in fixed-size blocks. One TLS record per ~1 KB
394	    //    keeps throughput reasonable (vs one record per line). yield() after every
395	    //    chunk so we don't starve the WiFi task or trip the task watchdog.
396	    const uint32_t total_bytes = log_file.size();
397	    uint32_t sent_bytes = 0;
398	    uint32_t last_log = 0;
399	    while (log_file.available()) {
400	      int n = log_file.read((uint8_t*)chunk_buffer, CHUNK_BUF_SZ);
401	      if (n <= 0) break;
402	      sprintf(chunk_header, "%X\r\n", n);
403	      client.write((const uint8_t*)chunk_header, strlen(chunk_header));
404	      client.write((const uint8_t*)chunk_buffer, n);
405	      client.write((const uint8_t*)"\r\n", 2);
406	      sent_bytes += n;
407	      if (sent_bytes - last_log >= 8192) {
408	        M5_LOGD("Upload progress: %u / %u bytes", sent_bytes, total_bytes);
409	        last_log = sent_bytes;
410	      }
411	      yield();
412	    }
413	    M5_LOGD("Upload streaming complete: %u bytes", sent_bytes);
414	
415	    // 3. Send the closing boundary as a chunk (with CRLF prefix to terminate file body)
416	    sprintf(chunk_buffer, "\r\n--%s--\r\n", boundary);
417	    chunk_length = strlen(chunk_buffer);
