283	void FlightModeScreen::enter_screen(Controller& controller) {
284	  M5_LOGI("Entering Cosmic mode - optimizing power");
285	  
286	  // Set the last mode to flight mode
287	  LocalStorage& settings = const_cast<LocalStorage&>(controller.get_settings());
288	  settings.set_last_mode(LocalStorage::e_operational_mode_flight, true);
289	  
290	  // Enter low power mode
291	  // Note: Core2 runs at 80MHz always (set at boot), CoreS3 reduces to 80MHz here
292	  PowerManager::enterLowPowerMode(false);
293	  
294	  // Start logging by default if manual logging is disabled
295	  if (!controller.get_settings().get_manual_logging()) {
296	    controller.set_handler_active(k_handler_flight_logger, true);
297	    _currently_logging = true;
298	    set_status_message(F(" STARTED LOGGING COSMIC "));
299	  }
300	  
301	  // We'll set the GPS to AIR4 mode in the first render call
302	  // when we have access to the worker map
303	  force_next_render(); // Force render to apply GPS settings
304	  
305	  // Don't enable BLE for Cosmic mode to save power
306	  // controller.set_handler_active(k_handler_bluetooth_reporter, false);
307	  
308	  M5_LOGI("Cosmic mode activated with power optimizations");
309	}
310	
311	void FlightModeScreen::leave_screen(Controller& controller) {
312	  M5_LOGI("Leaving Cosmic mode - restoring normal power settings");
313	  
314	  // Stop logging when leaving the screen
315	  controller.set_handler_active(k_handler_flight_logger, false);
316	  _currently_logging = false;
317	  
318	  // Restore normal power settings
319	  PowerManager::exitLowPowerMode();
320	  
321	  // We need to get the worker map from the handle_input method, so we'll set the model back in that method
322	  // or in the enter_screen method of the next screen
323	  
324	  M5_LOGI("Cosmic mode deactivated - normal power settings restored");
325	}
