#ifndef BGEIGIEZEN_BUTTON_H_
#define BGEIGIEZEN_BUTTON_H_

#include <M5Unified.hpp>

#include <Arduino.h>
#include <Worker.hpp>

struct ButtonState {
  bool currentlyPressed;
  bool shortPress;
  bool longPress;
};

/**
 * M5 button wrapper as worker
 */
class ZenButton : public Worker<ButtonState> {
 public:
